suppressPackageStartupMessages({library(tidyverse);library(here)})
base<-here::here("replication","work","analysis","simulation","revised_primary1795")
addon<-here::here("replication","work","analysis","simulation","revised_primary1795_addon")
read<-function(dir,name)read_csv(file.path(dir,name),show_col_types=FALSE)
a<-read(addon,'replicate_annual.csv')
p<-read(here::here("replication","work","analysis"),'annual_inflation_1700_1834.csv')
annual<-a |> group_by(year) |> summarise(true_index=first(true_index),mean_estimated_index=mean(index_point),geometric_mean_estimated_index=exp(mean(log(index_point))),median_estimated_index=median(index_point),log_bias=mean(log_error),bias_mcse=sd(log_error)/sqrt(n()),coverage=mean(covered),.groups='drop') |>
 left_join(p |> select(year,empirical_point=index_point,empirical_q05=index_q05,empirical_median=index_draw_median,empirical_q95=index_q95),by='year') |>
 mutate(fixed_truth_below_empirical_q05=true_index<empirical_q05,fixed_truth_above_empirical_q95=true_index>empirical_q95)
write_csv(annual,file.path(addon,'fixed_path_anchor_annual_diagnosis.csv'))
defs<-list(ratio_1822_to1795=c(1822,1822,1795,1795),ratio_1818_1824_to1795=c(1818,1824,1795,1795),ratio_1834_to1795=c(1834,1834,1795,1795),ratio_1820_1824_to1770s=c(1820,1824,1770,1779),ratio_1787_to1785=c(1787,1787,1785,1785))
decomp<-imap_dfr(defs,function(y,id) a |> group_by(replicate) |> summarise(functional=id,numerator_log_error=log(mean(index_point[between(year,y[1],y[2])])/mean(true_index[between(year,y[1],y[2])])),denominator_log_error=log(mean(index_point[between(year,y[3],y[4])])/mean(true_index[between(year,y[3],y[4])])),.groups='drop') |> mutate(relative_log_error=numerator_log_error-denominator_log_error))
stored<-read(addon,'replicate_ratios.csv') |> select(replicate,functional,stored_log_error=log_error)
decomp<-decomp |> left_join(stored,by=c('replicate','functional'))
stopifnot(max(abs(decomp$relative_log_error-decomp$stored_log_error))<1e-12)
write_csv(decomp,file.path(addon,'fixed_path_anchor_replicate_decomposition.csv'))
out<-decomp |> group_by(functional) |> summarise(n=n(),mean_numerator_log_error=mean(numerator_log_error),mean_denominator_log_error=mean(denominator_log_error),mean_relative_log_error=mean(relative_log_error),relative_error_mcse=sd(relative_log_error)/sqrt(n()),.groups='drop')
write_csv(out,file.path(addon,'fixed_path_anchor_bias_decomposition.csv'))
ref<-file.path(base,'flagged_optimizer_refinement')
rc<-read(ref,'selected_refinement_functional_changes.csv');pc<-read(ref,'selected_refinement_peak_changes.csv');ac<-read(ref,'aggregate_annual_refinement_impact.csv');fc<-read(ref,'aggregate_functional_refinement_impact.csv')
impact<-tibble(max_individual_functional_log_change=max(abs(rc$point_log_change)),max_individual_endpoint_log_change=max(abs(c(rc$q05_log_change,rc$q95_log_change))),functional_coverage_events_changed=sum(rc$coverage_changed),max_individual_peak_probability_change=max(abs(c(pc$prob_change_before1825,pc$prob_change_before1826))),max_aggregate_functional_bias_change_in_mcse=max(fc$bias_change_in_mcse,na.rm=TRUE),max_aggregate_annual_metric_change_in_mcse=max(ac$change_in_mcse,na.rm=TRUE))
write_csv(impact,file.path(ref,'refinement_final_impact_summary.csv'))
print(annual |> filter(year%in%c(1785,1787,1795,1822,1834)),width=Inf)
print(out,width=Inf);print(impact,width=Inf)
